package com.notificationfeed;

import java.time.DateTimeException;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import lombok.Getter;

/**
 * A user-defined timestamp pattern using {@link DateTimeFormatter} syntax (e.g. {@code HH:mm:ss}), with
 * {@value #RELATIVE_TOKEN} standing in for the relative time (e.g. "2m ago").
 */
final class CustomTimestampFormat
{
	static final String RELATIVE_TOKEN = "{relative}";
	static final String INVALID = "invalid format";

	@Getter
	private final String pattern;

	/**
	 * Date/time formatters for the text between relative tokens; one more entry than there are tokens.
	 * A null entry is an empty segment. The list itself is null if the pattern is invalid.
	 */
	private final List<DateTimeFormatter> segments;

	private CustomTimestampFormat(String pattern, List<DateTimeFormatter> segments)
	{
		this.pattern = pattern;
		this.segments = segments;
	}

	static CustomTimestampFormat compile(String pattern)
	{
		if (pattern == null || pattern.trim().isEmpty())
		{
			return new CustomTimestampFormat(pattern, null);
		}

		List<DateTimeFormatter> segments = new ArrayList<>();
		int start = 0;
		while (true)
		{
			int token = pattern.indexOf(RELATIVE_TOKEN, start);
			String segment = pattern.substring(start, token < 0 ? pattern.length() : token);
			try
			{
				segments.add(segment.isEmpty() ? null : DateTimeFormatter.ofPattern(segment));
			}
			catch (IllegalArgumentException e)
			{
				return new CustomTimestampFormat(pattern, null);
			}
			if (token < 0)
			{
				return new CustomTimestampFormat(pattern, segments);
			}
			start = token + RELATIVE_TOKEN.length();
		}
	}

	/**
	 * Formats an epoch-millis timestamp. Returns null for a blank pattern (no timestamp shown) and
	 * {@link #INVALID} if the pattern can't be used.
	 */
	String format(long timestamp, long now)
	{
		if (pattern == null || pattern.trim().isEmpty())
		{
			return null;
		}
		if (segments == null)
		{
			return INVALID;
		}

		ZonedDateTime time = Instant.ofEpochMilli(timestamp).atZone(ZoneId.systemDefault());
		StringBuilder sb = new StringBuilder();
		try
		{
			for (int i = 0; i < segments.size(); i++)
			{
				if (i > 0)
				{
					sb.append(TimestampStyle.formatRelative(now - timestamp));
				}
				DateTimeFormatter segment = segments.get(i);
				if (segment != null)
				{
					segment.formatTo(time, sb);
				}
			}
		}
		catch (DateTimeException e)
		{
			return INVALID;
		}
		return sb.toString();
	}
}

package com.notificationfeed;

import lombok.Value;
import lombok.With;

/**
 * An immutable entry in the notification feed. Collapsed duplicates produce a new
 * entry with a bumped count and timestamp rather than mutating this one, so the
 * overlay can safely render a snapshot while notifications arrive on other threads.
 */
@Value
@With
public class FeedEntry
{
	String message;
	/**
	 * Epoch millis of the most recent occurrence of this message.
	 */
	long timestamp;
	int count;
}

package com.notificationfeed;

import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum FeedStyle
{
	CARDS("Separate boxes"),
	PANEL("Single panel");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.notificationfeed;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import javax.inject.Singleton;

/**
 * Thread-safe store of recent notifications, oldest first. Notifications may be fired
 * from any thread, while the overlay reads from the client thread.
 */
@Singleton
public class NotificationFeed
{
	private final Deque<FeedEntry> entries = new ArrayDeque<>();

	/**
	 * Adds a notification to the feed.
	 *
	 * @param collapseDuplicates if true and the newest entry has the same message, that
	 *                           entry's count and timestamp are bumped instead of adding a new one
	 * @param collapseWindowMs   a duplicate arriving this long or longer after the newest entry's
	 *                           last occurrence starts a new entry instead; 0 or less means no limit
	 * @param maxEntries         oldest entries beyond this count are dropped
	 */
	public synchronized void add(String message, long now, boolean collapseDuplicates, long collapseWindowMs, int maxEntries)
	{
		FeedEntry last = entries.peekLast();
		if (collapseDuplicates && last != null && last.getMessage().equals(message)
			&& (collapseWindowMs <= 0 || now - last.getTimestamp() < collapseWindowMs))
		{
			entries.pollLast();
			entries.addLast(last.withCount(last.getCount() + 1).withTimestamp(now));
		}
		else
		{
			entries.addLast(new FeedEntry(message, now, 1));
		}

		trim(maxEntries);
	}

	/**
	 * Removes expired entries and returns the remaining ones, oldest first.
	 *
	 * @param durationMs how long entries stay in the feed; 0 or less means forever
	 */
	public synchronized List<FeedEntry> snapshot(long now, long durationMs, int maxEntries)
	{
		if (durationMs > 0)
		{
			for (Iterator<FeedEntry> it = entries.iterator(); it.hasNext(); )
			{
				if (now - it.next().getTimestamp() >= durationMs)
				{
					it.remove();
				}
			}
		}

		trim(maxEntries);
		return new ArrayList<>(entries);
	}

	public synchronized void clear()
	{
		entries.clear();
	}

	private void trim(int maxEntries)
	{
		while (entries.size() > Math.max(maxEntries, 0))
		{
			entries.pollFirst();
		}
	}
}

package com.notificationfeed;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.FontType;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;
import net.runelite.client.ui.overlay.components.ComponentConstants;

@ConfigGroup(NotificationFeedConfig.GROUP)
public interface NotificationFeedConfig extends Config
{
	String GROUP = "notificationfeed";

	@ConfigSection(
		name = "Feed",
		description = "Which notifications are shown and for how long",
		position = 0
	)
	String feedSection = "feed";

	@ConfigSection(
		name = "Appearance",
		description = "How the feed looks",
		position = 1
	)
	String appearanceSection = "appearance";

	// Feed

	@Range(min = 1, max = 50)
	@ConfigItem(
		keyName = "maxEntries",
		name = "Max notifications",
		description = "Maximum number of notifications shown at once. Older ones are removed first.",
		position = 0,
		section = feedSection
	)
	default int maxEntries()
	{
		return 5;
	}

	@Units(Units.SECONDS)
	@Range(min = 0, max = 3600)
	@ConfigItem(
		keyName = "duration",
		name = "Display duration",
		description = "How long each notification stays in the feed. 0 keeps notifications until they are pushed out or cleared.",
		position = 1,
		section = feedSection
	)
	default int duration()
	{
		return 15;
	}

	@ConfigItem(
		keyName = "fadeOut",
		name = "Fade out",
		description = "Fade notifications out during their last second instead of removing them abruptly",
		position = 2,
		section = feedSection
	)
	default boolean fadeOut()
	{
		return true;
	}

	@ConfigItem(
		keyName = "newestFirst",
		name = "Newest on top",
		description = "Show the newest notification at the top of the feed instead of the bottom",
		position = 3,
		section = feedSection
	)
	default boolean newestFirst()
	{
		return true;
	}

	@ConfigItem(
		keyName = "collapseDuplicates",
		name = "Collapse duplicates",
		description = "Merge a notification with the previous one if the text is identical, showing a count instead",
		position = 4,
		section = feedSection
	)
	default boolean collapseDuplicates()
	{
		return true;
	}

	@Units(Units.MINUTES)
	@Range(min = 0, max = 1440)
	@ConfigItem(
		keyName = "collapseWindow",
		name = "Duplicate time limit",
		description = "When collapsing duplicates, a repeat that arrives at least this many minutes after the"
			+ " previous one starts a new line instead. 0 always collapses.",
		position = 5,
		section = feedSection
	)
	default int collapseWindow()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "showWhenEmpty",
		name = "Show when empty",
		description = "Keep the feed visible with a placeholder when there are no notifications."
			+ " The placeholder is always shown while holding Alt so the feed can be moved.",
		position = 6,
		section = feedSection
	)
	default boolean showWhenEmpty()
	{
		return false;
	}

	@ConfigItem(
		keyName = "ignoredNotifications",
		name = "Ignored notifications",
		description = "Notifications matching any of these lines are not shown. One per line; supports * wildcards"
			+ " and is case-insensitive. e.g. *is now idle*",
		position = 7,
		section = feedSection
	)
	default String ignoredNotifications()
	{
		return "";
	}

	// Appearance

	@ConfigItem(
		keyName = "style",
		name = "Style",
		description = "Show each notification in its own box, or all of them in one panel",
		position = 0,
		section = appearanceSection
	)
	default FeedStyle style()
	{
		return FeedStyle.CARDS;
	}

	@ConfigItem(
		keyName = "timestampStyle",
		name = "Timestamp",
		description = "Show when each notification was received",
		position = 1,
		section = appearanceSection
	)
	default TimestampStyle timestampStyle()
	{
		return TimestampStyle.TIME_24H;
	}

	@ConfigItem(
		keyName = "customTimestampFormat",
		name = "Custom timestamp",
		description = "Format used when Timestamp is set to Custom, e.g. HH:mm:ss."
			+ " See \"Custom timestamp format\" in the plugin's README for the full syntax.",
		position = 2,
		section = appearanceSection
	)
	default String customTimestampFormat()
	{
		return "HH:mm:ss";
	}

	@ConfigItem(
		keyName = "wrapText",
		name = "Wrap long text",
		description = "Wrap long notifications onto multiple lines instead of cutting them off."
			+ " Resize the feed by Alt-dragging its edge.",
		position = 3,
		section = appearanceSection
	)
	default boolean wrapText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "font",
		name = "Font",
		description = "Font used for notification text",
		position = 4,
		section = appearanceSection
	)
	default FontType font()
	{
		return FontType.REGULAR;
	}

	@ConfigItem(
		keyName = "textColor",
		name = "Text color",
		description = "Color of notification text",
		position = 5,
		section = appearanceSection
	)
	default Color textColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "timestampColor",
		name = "Timestamp color",
		description = "Color of timestamps and duplicate counts",
		position = 6,
		section = appearanceSection
	)
	default Color timestampColor()
	{
		return new Color(0xFF, 0x98, 0x1F);
	}

	@Alpha
	@ConfigItem(
		keyName = "backgroundColor",
		name = "Background color",
		description = "Background color of the feed",
		position = 7,
		section = appearanceSection
	)
	default Color backgroundColor()
	{
		return ComponentConstants.STANDARD_BACKGROUND_COLOR;
	}
}

package com.notificationfeed;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.BackgroundComponent;

class NotificationFeedOverlay extends Overlay
{
	private static final int DEFAULT_WIDTH = 225;
	private static final int MIN_WIDTH = 80;
	private static final int PADDING = 4;
	/**
	 * Vertical gap between entries: between boxes in card style, between text blocks in panel style.
	 */
	private static final int ENTRY_GAP = 2;
	private static final long FADE_MS = 1000;
	private static final String EMPTY_TEXT = "No notifications";
	private static final String TARGET = "Notification feed";
	private static final Font COUNT_FONT = FontManager.getRunescapeSmallFont();

	private final Client client;
	private final NotificationFeed feed;
	private final NotificationFeedConfig config;
	private final BackgroundComponent background = new BackgroundComponent();
	private CustomTimestampFormat customTimestampFormat = CustomTimestampFormat.compile(null);

	@Inject
	NotificationFeedOverlay(NotificationFeedPlugin plugin, Client client, NotificationFeed feed, NotificationFeedConfig config)
	{
		super(plugin);
		this.client = client;
		this.feed = feed;
		this.config = config;

		setPosition(OverlayPosition.TOP_LEFT);
		setResizable(true);
		setMinimumSize(MIN_WIDTH);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Clear", TARGET, e -> feed.clear());
		addMenuEntry(MenuAction.RUNELITE_OVERLAY_CONFIG, OverlayManager.OPTION_CONFIGURE, TARGET);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		long now = System.currentTimeMillis();
		long durationMs = config.duration() * 1000L;
		List<FeedEntry> entries = feed.snapshot(now, durationMs, config.maxEntries());

		g.setFont(config.font().getFont());
		FontMetrics fm = g.getFontMetrics();
		int width = getPreferredSize() != null ? Math.max(getPreferredSize().width, MIN_WIDTH) : DEFAULT_WIDTH;

		if (entries.isEmpty())
		{
			// Holding Alt puts overlays in move mode; an overlay that renders nothing can't be grabbed
			if (!config.showWhenEmpty() && !client.isKeyPressed(KeyCode.KC_ALT))
			{
				return null;
			}
			return renderEmpty(g, fm, width);
		}

		if (config.newestFirst())
		{
			Collections.reverse(entries);
		}

		List<Block> blocks = layout(entries, fm, g.getFontMetrics(COUNT_FONT), width - 2 * PADDING, now, durationMs);
		int lineHeight = fm.getHeight();

		if (config.style() == FeedStyle.PANEL)
		{
			int height = 2 * PADDING + (blocks.size() - 1) * ENTRY_GAP;
			for (Block block : blocks)
			{
				height += block.lines.size() * lineHeight;
			}
			drawBackground(g, 0, width, height);

			int y = PADDING;
			for (Block block : blocks)
			{
				int top = y;
				withAlpha(g, block.alpha, () -> drawBlock(g, fm, block, PADDING, top));
				y += block.lines.size() * lineHeight + ENTRY_GAP;
			}
			return new Dimension(width, height);
		}

		int y = 0;
		for (Block block : blocks)
		{
			int height = block.lines.size() * lineHeight + 2 * PADDING;
			int top = y;
			withAlpha(g, block.alpha, () ->
			{
				drawBackground(g, top, width, height);
				drawBlock(g, fm, block, PADDING, top + PADDING);
			});
			y += height + ENTRY_GAP;
		}
		return new Dimension(width, y - ENTRY_GAP);
	}

	private Dimension renderEmpty(Graphics2D g, FontMetrics fm, int width)
	{
		int height = fm.getHeight() + 2 * PADDING;
		drawBackground(g, 0, width, height);
		String text = TextWrapper.truncate(EMPTY_TEXT, fm, width - 2 * PADDING);
		drawText(g, text, PADDING, PADDING + fm.getAscent(), Color.GRAY);
		return new Dimension(width, height);
	}

	private List<Block> layout(List<FeedEntry> entries, FontMetrics fm, FontMetrics countFm, int textWidth,
		long now, long durationMs)
	{
		TimestampStyle timestampStyle = config.timestampStyle();
		String customPattern = config.customTimestampFormat();
		if (!Objects.equals(customPattern, customTimestampFormat.getPattern()))
		{
			customTimestampFormat = CustomTimestampFormat.compile(customPattern);
		}
		int spaceWidth = fm.stringWidth(" ");
		List<Block> blocks = new ArrayList<>(entries.size());

		for (FeedEntry entry : entries)
		{
			String timestamp = timestampStyle.format(entry.getTimestamp(), now, customTimestampFormat);
			String prefix = timestamp != null ? timestamp : "";
			int prefixWidth = prefix.isEmpty() ? 0 : fm.stringWidth(prefix) + spaceWidth;

			String count = entry.getCount() > 1 ? "x" + entry.getCount() : "";
			int countWidth = count.isEmpty() ? 0 : spaceWidth + countFm.stringWidth(count);

			List<String> lines;
			if (config.wrapText())
			{
				lines = new ArrayList<>(TextWrapper.wrap(entry.getMessage(), fm, textWidth - prefixWidth, textWidth));
				// Push the count onto its own line if it doesn't fit after the last line of text
				int last = lines.size() - 1;
				int lineStart = last == 0 ? prefixWidth : 0;
				if (countWidth > 0 && lineStart + fm.stringWidth(lines.get(last)) + countWidth > textWidth)
				{
					lines.add("");
				}
			}
			else
			{
				lines = Collections.singletonList(
					TextWrapper.truncate(entry.getMessage(), fm, textWidth - prefixWidth - countWidth));
			}

			int last = lines.size() - 1;
			String lastLine = lines.get(last);
			int countX = (last == 0 ? prefixWidth : 0)
				+ (lastLine.isEmpty() ? 0 : fm.stringWidth(lastLine) + spaceWidth);

			blocks.add(new Block(prefix, prefixWidth, lines, count, countX, alpha(entry, now, durationMs)));
		}
		return blocks;
	}

	private float alpha(FeedEntry entry, long now, long durationMs)
	{
		if (!config.fadeOut() || durationMs <= 0)
		{
			return 1f;
		}
		long remaining = durationMs - (now - entry.getTimestamp());
		return Math.max(0f, Math.min(1f, remaining / (float) Math.min(FADE_MS, durationMs)));
	}

	private void drawBlock(Graphics2D g, FontMetrics fm, Block block, int x, int top)
	{
		int baseline = top + fm.getAscent();
		if (!block.prefix.isEmpty())
		{
			drawText(g, block.prefix, x, baseline, config.timestampColor());
		}

		Color textColor = config.textColor();
		for (int i = 0; i < block.lines.size(); i++)
		{
			int lineX = i == 0 ? x + block.prefixWidth : x;
			drawText(g, block.lines.get(i), lineX, baseline + i * fm.getHeight(), textColor);
		}

		if (!block.count.isEmpty())
		{
			Font font = g.getFont();
			g.setFont(COUNT_FONT);
			int countBaseline = baseline + (block.lines.size() - 1) * fm.getHeight();
			drawText(g, block.count, x + block.countX, countBaseline, config.timestampColor());
			g.setFont(font);
		}
	}

	private void drawBackground(Graphics2D g, int y, int width, int height)
	{
		background.setBackgroundColor(config.backgroundColor());
		background.setRectangle(new Rectangle(0, y, width, height));
		background.render(g);
	}

	private static void drawText(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static void withAlpha(Graphics2D g, float alpha, Runnable draw)
	{
		if (alpha >= 1f)
		{
			draw.run();
			return;
		}

		Composite original = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		try
		{
			draw.run();
		}
		finally
		{
			g.setComposite(original);
		}
	}

	@Value
	private static class Block
	{
		String prefix;
		int prefixWidth;
		List<String> lines;
		/**
		 * Duplicate count such as "x3", drawn in a smaller font after the last line; empty if none.
		 */
		String count;
		/**
		 * X offset of the count from the start of the last line's row.
		 */
		int countX;
		float alpha;
	}
}

package com.notificationfeed;

import com.google.common.base.Splitter;
import com.google.inject.Provides;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NotificationFired;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

@Slf4j
@PluginDescriptor(
	name = "Notification Feed",
	description = "Shows a live, movable feed of RuneLite notifications inside the game window",
	tags = {"notification", "notifications", "feed", "log", "history", "overlay", "toast", "alert"}
)
public class NotificationFeedPlugin extends Plugin
{
	private static final Splitter LINE_SPLITTER = Splitter.on('\n').trimResults().omitEmptyStrings();

	@Inject
	private NotificationFeedConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private NotificationFeedOverlay overlay;

	@Inject
	private NotificationFeed feed;

	private volatile List<String> ignoredPatterns = Collections.emptyList();

	@Provides
	NotificationFeedConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(NotificationFeedConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadIgnoredPatterns();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		feed.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (NotificationFeedConfig.GROUP.equals(event.getGroup()) && "ignoredNotifications".equals(event.getKey()))
		{
			loadIgnoredPatterns();
		}
	}

	// Fired by RuneLite's Notifier for every enabled notification, whether or not the client is
	// focused, and by plugins such as Watchdog that post the event directly. May be on any thread.
	@Subscribe
	public void onNotificationFired(NotificationFired event)
	{
		String message = clean(event.getMessage());
		if (message.isEmpty() || isIgnored(message))
		{
			return;
		}

		log.debug("Notification: {}", message);
		feed.add(message, System.currentTimeMillis(), config.collapseDuplicates(),
			config.collapseWindow() * 60_000L, config.maxEntries());
	}

	static String clean(String message)
	{
		if (message == null)
		{
			return "";
		}
		return Text.removeTags(message).replaceAll("\\s+", " ").trim();
	}

	private boolean isIgnored(String message)
	{
		for (String pattern : ignoredPatterns)
		{
			if (WildcardMatcher.matches(pattern, message))
			{
				return true;
			}
		}
		return false;
	}

	private void loadIgnoredPatterns()
	{
		ignoredPatterns = LINE_SPLITTER.splitToList(config.ignoredNotifications());
	}
}

package com.notificationfeed;

import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.List;

final class TextWrapper
{
	private static final String ELLIPSIS = "...";

	private TextWrapper()
	{
	}

	/**
	 * Word-wraps text to fit within maxWidth pixels. Words wider than maxWidth are
	 * broken across lines. Always returns at least one line.
	 *
	 * @param firstLineWidth width available on the first line, which may be narrower than
	 *                       maxWidth to leave room for a prefix such as a timestamp. If the
	 *                       first word doesn't fit there but would fit on a full line, the
	 *                       first line is left empty.
	 */
	static List<String> wrap(String text, FontMetrics fm, int firstLineWidth, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		String line = "";

		for (String word : text.split(" "))
		{
			if (word.isEmpty())
			{
				continue;
			}

			String candidate = line.isEmpty() ? word : line + " " + word;
			if (fm.stringWidth(candidate) <= limit(lines, firstLineWidth, maxWidth))
			{
				line = candidate;
				continue;
			}

			if (!line.isEmpty())
			{
				lines.add(line);
				line = "";
			}

			if (fm.stringWidth(word) <= maxWidth)
			{
				if (fm.stringWidth(word) > limit(lines, firstLineWidth, maxWidth))
				{
					// Only possible on a narrowed first line
					lines.add("");
				}
				line = word;
				continue;
			}

			// Break words that are too long to fit on a line of their own
			while (word.length() > 1 && fm.stringWidth(word) > limit(lines, firstLineWidth, maxWidth))
			{
				int fit = fitChars(word, fm, limit(lines, firstLineWidth, maxWidth));
				lines.add(word.substring(0, fit));
				word = word.substring(fit);
			}
			line = word;
		}

		if (!line.isEmpty() || lines.isEmpty())
		{
			lines.add(line);
		}
		return lines;
	}

	private static int limit(List<String> lines, int firstLineWidth, int maxWidth)
	{
		return lines.isEmpty() ? firstLineWidth : maxWidth;
	}

	/**
	 * Truncates text with an ellipsis so that it fits within maxWidth pixels.
	 */
	static String truncate(String text, FontMetrics fm, int maxWidth)
	{
		if (fm.stringWidth(text) <= maxWidth)
		{
			return text;
		}

		int available = maxWidth - fm.stringWidth(ELLIPSIS);
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end)) > available)
		{
			end--;
		}
		return text.substring(0, end).trim() + ELLIPSIS;
	}

	/**
	 * Number of leading chars of word that fit within maxWidth, minimum 1.
	 */
	private static int fitChars(String word, FontMetrics fm, int maxWidth)
	{
		int n = 1;
		while (n < word.length() && fm.stringWidth(word.substring(0, n + 1)) <= maxWidth)
		{
			n++;
		}
		return n;
	}
}

package com.notificationfeed;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
public enum TimestampStyle
{
	NONE("None", null),
	TIME_24H("24-hour (13:05)", DateTimeFormatter.ofPattern("HH:mm")),
	TIME_24H_SECONDS("24-hour (13:05:09)", DateTimeFormatter.ofPattern("HH:mm:ss")),
	TIME_12H("12-hour (1:05 PM)", DateTimeFormatter.ofPattern("h:mm a")),
	TIME_12H_SECONDS("12-hour (1:05:09 PM)", DateTimeFormatter.ofPattern("h:mm:ss a")),
	RELATIVE("Relative (2m ago)", null),
	CUSTOM("Custom", null);

	private final String name;
	private final DateTimeFormatter formatter;

	/**
	 * Formats an epoch-millis timestamp, or returns null when no timestamp should be shown.
	 *
	 * @param custom the user's pattern, used only by {@link #CUSTOM}
	 */
	String format(long timestamp, long now, CustomTimestampFormat custom)
	{
		switch (this)
		{
			case NONE:
				return null;
			case RELATIVE:
				return formatRelative(now - timestamp);
			case CUSTOM:
				return custom.format(timestamp, now);
			default:
				return formatter.format(Instant.ofEpochMilli(timestamp).atZone(ZoneId.systemDefault()));
		}
	}

	static String formatRelative(long elapsedMs)
	{
		long seconds = Math.max(elapsedMs, 0) / 1000;
		if (seconds < 5)
		{
			return "now";
		}
		if (seconds < 60)
		{
			return seconds + "s ago";
		}
		long minutes = seconds / 60;
		if (minutes < 60)
		{
			return minutes + "m ago";
		}
		long hours = minutes / 60;
		if (hours < 24)
		{
			return hours + "h ago";
		}
		return (hours / 24) + "d ago";
	}

	@Override
	public String toString()
	{
		return name;
	}
}

