package com.notificationfeed;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class NotificationFeedTest
{
	private final NotificationFeed feed = new NotificationFeed();

	@Test
	public void keepsEntriesOldestFirst()
	{
		feed.add("a", 0, true, 0, 5);
		feed.add("b", 1, true, 0, 5);

		List<FeedEntry> entries = feed.snapshot(2, 0, 5);
		assertEquals(2, entries.size());
		assertEquals("a", entries.get(0).getMessage());
		assertEquals("b", entries.get(1).getMessage());
	}

	@Test
	public void collapsesConsecutiveDuplicates()
	{
		feed.add("a", 0, true, 0, 5);
		feed.add("a", 10, true, 0, 5);
		feed.add("b", 20, true, 0, 5);
		feed.add("a", 30, true, 0, 5);

		List<FeedEntry> entries = feed.snapshot(30, 0, 5);
		assertEquals(3, entries.size());
		assertEquals(new FeedEntry("a", 10, 2), entries.get(0));
		assertEquals(new FeedEntry("a", 30, 1), entries.get(2));
	}

	@Test
	public void duplicateWithinWindowCollapses()
	{
		feed.add("a", 0, true, 1000, 5);
		feed.add("a", 999, true, 1000, 5);

		List<FeedEntry> entries = feed.snapshot(999, 0, 5);
		assertEquals(1, entries.size());
		assertEquals(2, entries.get(0).getCount());
	}

	@Test
	public void duplicateAfterWindowStartsNewEntry()
	{
		feed.add("a", 0, true, 1000, 5);
		feed.add("a", 1000, true, 1000, 5);

		List<FeedEntry> entries = feed.snapshot(1000, 0, 5);
		assertEquals(2, entries.size());
		assertEquals(new FeedEntry("a", 1000, 1), entries.get(1));
	}

	@Test
	public void windowIsMeasuredFromLatestOccurrence()
	{
		// Each repeat is within the window of the previous one, so they keep collapsing
		// even though the last is well past the window from the first
		feed.add("a", 0, true, 1000, 5);
		feed.add("a", 800, true, 1000, 5);
		feed.add("a", 1600, true, 1000, 5);

		List<FeedEntry> entries = feed.snapshot(1600, 0, 5);
		assertEquals(1, entries.size());
		assertEquals(3, entries.get(0).getCount());
	}

	@Test
	public void keepsDuplicatesWhenNotCollapsing()
	{
		feed.add("a", 0, false, 0, 5);
		feed.add("a", 10, false, 0, 5);

		assertEquals(2, feed.snapshot(10, 0, 5).size());
	}

	@Test
	public void dropsOldestBeyondMax()
	{
		for (int i = 0; i < 5; i++)
		{
			feed.add("m" + i, i, true, 0, 3);
		}

		List<FeedEntry> entries = feed.snapshot(5, 0, 3);
		assertEquals(3, entries.size());
		assertEquals("m2", entries.get(0).getMessage());

		// Lowering the max later trims on the next snapshot
		assertEquals("m4", feed.snapshot(5, 0, 1).get(0).getMessage());
	}

	@Test
	public void expiresEntriesAfterDuration()
	{
		feed.add("old", 0, true, 0, 5);
		feed.add("new", 900, true, 0, 5);

		List<FeedEntry> entries = feed.snapshot(1000, 1000, 5);
		assertEquals(1, entries.size());
		assertEquals("new", entries.get(0).getMessage());
	}

	@Test
	public void collapsedDuplicateRestartsExpiry()
	{
		feed.add("a", 0, true, 0, 5);
		feed.add("a", 900, true, 0, 5);

		assertEquals(1, feed.snapshot(1500, 1000, 5).size());
	}

	@Test
	public void zeroDurationNeverExpires()
	{
		feed.add("a", 0, true, 0, 5);
		assertEquals(1, feed.snapshot(Long.MAX_VALUE, 0, 5).size());
	}

	@Test
	public void clearRemovesEverything()
	{
		feed.add("a", 0, true, 0, 5);
		feed.clear();
		assertTrue(feed.snapshot(0, 0, 5).isEmpty());
	}
}

package com.notificationfeed;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TextWrapperTest
{
	// Monospaced so widths are predictable: every char is the same width
	private static final FontMetrics FM = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB)
		.createGraphics()
		.getFontMetrics(new Font(Font.MONOSPACED, Font.PLAIN, 12));
	private static final int CHAR = FM.charWidth('a');

	@Test
	public void shortTextIsOneLine()
	{
		assertEquals(Collections.singletonList("hello world"), TextWrapper.wrap("hello world", FM, 20 * CHAR, 20 * CHAR));
	}

	@Test
	public void wrapsAtWordBoundaries()
	{
		assertEquals(Arrays.asList("aaa bbb", "ccc"), TextWrapper.wrap("aaa bbb ccc", FM, 8 * CHAR, 8 * CHAR));
	}

	@Test
	public void breaksWordsLongerThanLine()
	{
		assertEquals(Arrays.asList("abcd", "efgh", "ij"), TextWrapper.wrap("abcdefghij", FM, 4 * CHAR, 4 * CHAR));
	}

	@Test
	public void narrowFirstLine()
	{
		assertEquals(Arrays.asList("aa", "bbb ccc"), TextWrapper.wrap("aa bbb ccc", FM, 3 * CHAR, 8 * CHAR));
	}

	@Test
	public void firstLineLeftEmptyWhenFirstWordOnlyFitsFullWidth()
	{
		assertEquals(Arrays.asList("", "abcdef"), TextWrapper.wrap("abcdef", FM, 3 * CHAR, 8 * CHAR));
	}

	@Test
	public void collapsesRepeatedSpaces()
	{
		assertEquals(Collections.singletonList("a b"), TextWrapper.wrap("a   b", FM, 20 * CHAR, 20 * CHAR));
	}

	@Test
	public void emptyTextIsOneEmptyLine()
	{
		assertEquals(Collections.singletonList(""), TextWrapper.wrap("", FM, 20 * CHAR, 20 * CHAR));
	}

	@Test
	public void truncateLeavesShortTextAlone()
	{
		assertEquals("hello", TextWrapper.truncate("hello", FM, 10 * CHAR));
	}

	@Test
	public void truncateAddsEllipsis()
	{
		String result = TextWrapper.truncate("hello world", FM, 8 * CHAR);
		assertEquals("hello...", result);
		assertTrue(FM.stringWidth(result) <= 8 * CHAR);
	}

	@Test
	public void wrappedLinesFitWidth()
	{
		List<String> lines = TextWrapper.wrap("Your character is now idle and should probably do something", FM, 12 * CHAR, 15 * CHAR);
		assertTrue(FM.stringWidth(lines.get(0)) <= 12 * CHAR);
		for (String line : lines.subList(1, lines.size()))
		{
			assertTrue(line, FM.stringWidth(line) <= 15 * CHAR);
		}
	}
}

package com.notificationfeed;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.time.LocalDateTime;
import java.time.ZoneId;
import org.junit.Test;

public class TimestampStyleTest
{
	private static final long TIME = LocalDateTime.of(2026, 11, 16, 13, 5, 9)
		.atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();

	@Test
	public void relative()
	{
		assertEquals("now", TimestampStyle.formatRelative(-50));
		assertEquals("now", TimestampStyle.formatRelative(4_999));
		assertEquals("5s ago", TimestampStyle.formatRelative(5_000));
		assertEquals("1m ago", TimestampStyle.formatRelative(60_000));
		assertEquals("2h ago", TimestampStyle.formatRelative(2 * 3_600_000));
		assertEquals("3d ago", TimestampStyle.formatRelative(3 * 86_400_000L));
	}

	@Test
	public void noneFormatsToNull()
	{
		assertNull(TimestampStyle.NONE.format(0, 0, CustomTimestampFormat.compile("HH:mm")));
	}

	@Test
	public void customPattern()
	{
		assertEquals("13:05:09", custom("HH:mm:ss", TIME));
		assertEquals("1:05 PM 16/11", custom("h:mm a dd/MM", TIME));
		assertEquals("13:05 at Mon", custom("HH:mm 'at' EEE", TIME));
	}

	@Test
	public void customRelative()
	{
		long now = TIME + 120_000;
		assertEquals("2m ago", custom("{relative}", now));
		assertEquals("13:05 (2m ago)", custom("HH:mm ({relative})", now));
		assertEquals("2m ago, 13:05, 2m ago", custom("{relative}, HH:mm, {relative}", now));
	}

	@Test
	public void customBlankShowsNothing()
	{
		assertNull(custom("", TIME));
		assertNull(custom("  ", TIME));
		assertNull(custom(null, TIME));
	}

	@Test
	public void customInvalid()
	{
		assertEquals(CustomTimestampFormat.INVALID, custom("HH:mm 'unterminated", TIME));
		assertEquals(CustomTimestampFormat.INVALID, custom("ZZZZZZ", TIME));
	}

	private static String custom(String pattern, long now)
	{
		return TimestampStyle.CUSTOM.format(TIME, now, CustomTimestampFormat.compile(pattern));
	}
}
